def maxScore(s):
    ones_total = s.count('1')
    max_score = float('-inf')
    left_zeros = left_ones = 0
    for i in range(len(s)-1):
        if s[i] == '0':
            left_zeros += 1
        else:
            left_ones += 1
        # right ones = total ones - left encountered so far
        score = left_zeros + (ones_total - left_ones)
        if score > max_score:
            max_score = score
    return max_score
